driver.probe.mjs:
// Measurement driver: runs the scriptc compiler from the worktree SOURCE (via tsx).
// usage: tsx probe.mjs <analyze|compile> <entry> <outDir> <target> [optimization=release] [npmStatic=auto|none|a,b]
import { mkdir, readFile, writeFile, stat } from "node:fs/promises";
import { resolve, join } from "node:path";
import { createHash } from "node:crypto";
import { spawnSync } from "node:child_process";
import { pathToFileURL } from "node:url";

const wt = process.env.COMPILER_ROOT ?? process.env.WT_DIR;
if (!wt) throw new Error("WT_DIR is required");
const { analyze, compile } = await import(pathToFileURL(join(wt, "packages/compiler/src/index.ts")).href);

const [mode, entryArg, outputArg, target = "node26", optimization = "release", npm = "auto"] = process.argv.slice(2);
const entry = resolve(entryArg), outDir = resolve(outputArg);
await mkdir(outDir, { recursive: true });
const sha = (b) => createHash("sha256").update(b).digest("hex");
const options = {
  backend: "rust", allowEngine: false, target, optimization,
  ...(npm === "none" ? {} : { npmStatic: npm === "auto" ? "auto" : npm.split(",") }),
};
const git = (args) => spawnSync("git", args, { cwd: wt, encoding: "utf8" }).stdout.trim();
const report = {
  createdAt: new Date().toISOString(), node: process.version, mode, entry, options,
  entrySha256: sha(await readFile(entry)),
  compiler: { root: wt, commit: process.env.COMPILER_SNAPSHOT ?? git(["rev-parse", "HEAD"]), dirty: process.env.COMPILER_SNAPSHOT ? false : git(["status", "--porcelain=v1"]).length > 0, rustc: spawnSync("rustc", ["--version"], { encoding: "utf8" }).stdout.trim() },
};
const byCode = (list) => {
  const m = {};
  for (const d of list ?? []) m[d.code] = (m[d.code] ?? 0) + 1;
  return Object.fromEntries(Object.entries(m).sort((a, b) => b[1] - a[1]));
};
const start = performance.now();
try {
  if (mode === "analyze") {
    const result = analyze(entry, options);
    const c = result.coverage;
    report.coverage = c;
    report.summary = {
      preflightFailed: c.preflightFailed, stats: c.stats,
      diagnostics: c.diagnostics.length, diagnosticsByCode: byCode(c.diagnostics),
      runtimeFences: (c.runtimeFences ?? []).length, runtimeFencesByCode: byCode(c.runtimeFences),
      execution: c.execution ?? null, npmStatic: c.npmStatic ?? [],
      sources: result.sourceTexts.size,
    };
    report.ok = !c.preflightFailed && c.diagnostics.length === 0 && c.stats.statementsFailed === 0;
    report.sources = [...result.sourceTexts].map(([file, text]) => ({ file, bytes: Buffer.byteLength(text), sha256: sha(text) })).sort((a, b) => a.file.localeCompare(b.file));
  } else {
    const result = await compile(entry, { ...options, outDir, outPath: join(outDir, "program") });
    const { sourceTexts, ...serializable } = result;
    report.result = serializable;
    report.ok = result.ok;
    report.summary = result.ok ? {
      ok: true, execution: result.execution, runtimeFences: (result.runtimeFences ?? []).length, runtimeFencesByCode: byCode(result.runtimeFences),
      safetyProfile: result.safetyProfile ?? null,
      binary: result.binaryPath, binaryBytes: (await stat(result.binaryPath)).size, binarySha256: sha(await readFile(result.binaryPath)),
      generatedSource: result.sourcePath ?? null,
      generatedSourceBytes: result.sourcePath ? (await stat(result.sourcePath)).size : null,
      generatedSourceSha256: result.sourcePath ? sha(await readFile(result.sourcePath)) : null,
    } : { ok: false, diagnostics: result.diagnostics.length, diagnosticsByCode: byCode(result.diagnostics) };
  }
} catch (error) { report.ok = false; report.exception = { name: error.name, message: error.message, stack: error.stack }; }
report.milliseconds = Math.round(performance.now() - start);
report.peakRssKiB = process.resourceUsage().maxRSS;
await writeFile(join(outDir, `${mode}.json`), JSON.stringify(report, null, 2) + "\n");
console.log(JSON.stringify({ mode, target, optimization, npm, ok: report.ok, milliseconds: report.milliseconds, peakRssKiB: report.peakRssKiB, summary: report.summary, exception: report.exception?.message }, null, 1));
process.exitCode = report.ok ? 0 : 1;
